//! P32: DSS7 variants with no corpus data, in files written by HEC's C library.
//!
//! Fixtures (`fixtures/public/`, see the README rows): `synthetic_notes_quality7.dss`,
//! `synthetic_irregular_variants7.dss`, `synthetic_catalog_ops7.dss`. They were written
//! through the public API of HEC's C library (heclib built from hec-dss `f14554d`,
//! `ztsStore`, `zaliasAdd`, `zaliasRemove`, `zdelete`, `zundelete`, `zrename`) (file version `7-JA`); they are not regenerated by the tests. All names
//! and values are invented; the value formulas below are the writer's.
//!
//! The expected values were checked against HEC: the C library (`ztsRetrieve`,
//! `zcatalog`, `zaliasGetPrimary`) agrees with the engine on every
//! one of 106 record, dataset, window, catalog and alias requests, and Monolith 3.3.27 on
//! 43 of 44 record reads (the exception is in
//! `second_granularity_far_past_and_future`).
//!
//! With `P32_DUMP_DIR=<dir>` set, `engine_dump` reads request lists `<dir>/req/<name>.txt`
//! and writes the engine's answers to `<dir>/engine_<name>.jsonl`, so they can be compared
//! with HEC's C library answering the same requests. Without the variable it does nothing.

use dss_core::dss7::interval::{parse_date, ymd_to_julian};
use dss_core::dss7::{Dss7File, Dss7Ts, TsReadOptions, TsWindow};
use dss_core::{IrregularBlock, RecordStatus, TsKind, TsValues};
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

const FILES: [(&str, &str); 3] = [
    ("notes", "synthetic_notes_quality7.dss"),
    ("irreg", "synthetic_irregular_variants7.dss"),
    ("catalog", "synthetic_catalog_ops7.dss"),
];

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures/public")
        .join(name)
}

fn jstr(s: &[u8]) -> String {
    let mut o = String::from("\"");
    for &c in s {
        match c {
            b'"' | b'\\' => {
                o.push('\\');
                o.push(c as char);
            }
            32..=126 => o.push(c as char),
            _ => {
                let _ = write!(o, "\\u{:04x}", c);
            }
        }
    }
    o.push('"');
    o
}

fn ints<T: std::fmt::Display>(v: &[T]) -> String {
    let parts: Vec<String> = v.iter().map(|x| x.to_string()).collect();
    format!("[{}]", parts.join(","))
}

/// HEC date and `hhmm` time (as in the request file) to seconds since the HEC epoch.
fn hec_time(date: &str, hhmm: &str) -> i64 {
    let j = parse_date(date.as_bytes()).expect("date");
    let t: i64 = hhmm.parse().expect("time");
    j * 86_400 + (t / 100) * 3600 + (t % 100) * 60
}

fn ts_json(kind: &str, req: &str, r: Result<Dss7Ts, String>) -> String {
    let r = match r {
        Ok(r) => r,
        Err(e) => {
            return format!(
                "{{\"kind\":\"{kind}\",\"request\":{},\"status\":-1,\"error\":{}}}",
                jstr(req.as_bytes()),
                jstr(e.as_bytes())
            )
        }
    };
    let vals: Vec<String> = match &r.ts.values {
        TsValues::F32(v) => v.iter().map(|x| format!("\"{x:?}\"")).collect(),
        TsValues::F64(v) => v.iter().map(|x| format!("\"{x:?}\"")).collect(),
    };
    let size_each = match &r.ts.values {
        TsValues::F32(_) => 1,
        TsValues::F64(_) => 2,
    };
    let m = &r.meta;
    let qes = m.quality_element_size;
    let quality_words: Vec<i32> = if qes > 1 {
        m.quality_words.clone().unwrap_or_default()
    } else {
        r.ts.quality.clone().unwrap_or_default()
    };
    let cnotes: Vec<String> = m
        .cnotes
        .as_ref()
        .map(|c| c.iter().map(|s| jstr(s.as_bytes())).collect())
        .unwrap_or_default();
    format!(
        "{{\"kind\":\"{kind}\",\"request\":{},\"status\":0,\"pathname\":{},\"data_type\":{},\
\"n\":{},\"granularity\":{},\"julian_base\":{},\"offset\":{},\"precision\":{},\"pattern\":{},\
\"size_each\":{},\"units\":{},\"type\":{},\"time_zone\":{},\"seconds\":{},\"values\":[{}],\
\"quality_element_size\":{},\"quality\":{},\"inote_element_size\":{},\"inotes\":{},\
\"cnotes_present\":{},\"cnotes\":[{}],\"blocks_found\":{}}}",
        jstr(req.as_bytes()),
        jstr(&r.ts.pathname),
        r.ts.record_type,
        r.ts.len(),
        m.time_granularity_seconds,
        m.julian_base_date,
        m.time_offset_seconds,
        m.precision,
        u8::from(m.pattern),
        size_each,
        jstr(r.ts.units.as_bytes()),
        jstr(r.ts.data_type.as_bytes()),
        jstr(r.ts.time_zone.as_deref().unwrap_or("").as_bytes()),
        ints(&r.ts.times),
        vals.join(","),
        qes,
        ints(&quality_words),
        m.inotes_element_size,
        ints(m.inotes.as_deref().unwrap_or(&[])),
        u8::from(m.cnotes.is_some()),
        cnotes.join(","),
        m.blocks_found,
    )
}

fn dump_one(dir: &Path, name: &str, file: &str) {
    let req = std::fs::read_to_string(dir.join("req").join(format!("{name}.txt"))).unwrap();
    let mut f = Dss7File::open(fixture(file)).unwrap();
    let mut out = String::new();
    for line in req.lines() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let p: Vec<&str> = line.split('\t').collect();
        let label = p.join(" ");
        match p[0] {
            "CAT" => {
                let cat = f.catalog().unwrap();
                let mut items = Vec::new();
                for (e, m) in cat.catalog.entries.iter().zip(&cat.meta) {
                    items.push(format!(
                        "{{\"path\":{},\"type\":{},\"raw_status\":{},\"status\":\"{:?}\",\"duplicate\":{}}}",
                        jstr(&e.pathname),
                        e.record_type,
                        m.raw_status,
                        e.status,
                        u8::from(m.duplicate_of.is_some())
                    ));
                }
                let _ = writeln!(
                    out,
                    "{{\"kind\":\"engine_catalog\",\"entries\":[{}]}}",
                    items.join(",")
                );
            }
            "A" => {
                let r = f.lookup(p[1].as_bytes()).unwrap();
                let s = match r {
                    Some(rec) => format!(
                        "{{\"kind\":\"alias\",\"request\":{},\"status\":0,\"bin_status\":{},\"primary\":{}}}",
                        jstr(p[1].as_bytes()),
                        rec.status,
                        jstr(&rec.info.pathname)
                    ),
                    None => format!(
                        "{{\"kind\":\"alias\",\"request\":{},\"status\":-1,\"primary\":\"\"}}",
                        jstr(p[1].as_bytes())
                    ),
                };
                let _ = writeln!(out, "{s}");
            }
            "R" => {
                let r = match f.lookup(p[1].as_bytes()) {
                    Ok(Some(rec)) => f.read_ts_record(&rec).map_err(|e| e.to_string()),
                    Ok(None) => Err("not found".to_string()),
                    Err(e) => Err(e.to_string()),
                };
                let _ = writeln!(out, "{}", ts_json("R", &label, r));
            }
            "D" | "T" | "W" => {
                let window = if p[0] == "W" {
                    Some(TsWindow {
                        start: hec_time(p[2], p[3]),
                        end: hec_time(p[4], p[5]),
                    })
                } else {
                    None
                };
                let opts = TsReadOptions {
                    window,
                    trim_missing: p[0] == "T",
                };
                let r = f.read_ts(p[1].as_bytes(), &opts).map_err(|e| e.to_string());
                let _ = writeln!(out, "{}", ts_json(p[0], &label, r));
            }
            other => panic!("unknown request {other}"),
        }
    }
    std::fs::write(dir.join(format!("engine_{name}.jsonl")), out).unwrap();
}

#[test]
fn engine_dump() {
    let Ok(dir) = std::env::var("P32_DUMP_DIR") else {
        return;
    };
    let dir = PathBuf::from(dir);
    for (name, file) in FILES {
        dump_one(&dir, name, file);
    }
}

// ---------------------------------------------------------------- committed checks

const NOTES: &str = "synthetic_notes_quality7.dss";
const IRREG: &str = "synthetic_irregular_variants7.dss";
const CATALOG: &str = "synthetic_catalog_ops7.dss";
const FLT_MAX_NEG: f32 = -f32::MAX;

type File7 = Dss7File<std::fs::File>;

fn open(name: &str) -> File7 {
    let p = fixture(name);
    let size = std::fs::metadata(&p).unwrap().len();
    let want = match name {
        NOTES => 139_192,
        IRREG => 133_088,
        CATALOG => 131_912,
        _ => unreachable!(),
    };
    assert_eq!(
        size, want,
        "{name}: committed fixture changed (its SHA-256 is pinned in the Python test)"
    );
    Dss7File::open(p).unwrap()
}

/// Seconds since the HEC epoch for a civil date and seconds of day.
fn at(y: i64, m: i64, d: i64, secs: i64) -> i64 {
    ymd_to_julian(y, m, d) * 86_400 + secs
}

fn record(f: &mut File7, path: &str) -> Dss7Ts {
    let rec = f.lookup(path.as_bytes()).unwrap().expect(path);
    f.read_ts_record(&rec).unwrap()
}

fn dataset(f: &mut File7, path: &str, window: Option<(i64, i64)>) -> Dss7Ts {
    let opts = TsReadOptions {
        window: window.map(|(start, end)| TsWindow { start, end }),
        trim_missing: false,
    };
    f.read_ts(path.as_bytes(), &opts).unwrap()
}

fn f32s(r: &Dss7Ts) -> &[f32] {
    match &r.ts.values {
        TsValues::F32(v) => v,
        TsValues::F64(_) => panic!("expected floats"),
    }
}

fn f64s(r: &Dss7Ts) -> &[f64] {
    match &r.ts.values {
        TsValues::F64(v) => v,
        TsValues::F32(_) => panic!("expected doubles"),
    }
}

/// Writer value formulas (`fill_values`).
fn fv(base: f32, i: usize) -> f32 {
    base + i as f32 * 0.25
}

fn dv(base: f64, i: usize) -> f64 {
    base + i as f64 * 0.125
}

fn fvs(base: f32, r: std::ops::Range<usize>) -> Vec<f32> {
    r.map(|i| fv(base, i)).collect()
}

fn dvs(base: f64, r: std::ops::Range<usize>) -> Vec<f64> {
    r.map(|i| dv(base, i)).collect()
}

/// Writer note formula (`make_notes`).
fn note(tag: &str, i: usize) -> String {
    if i % 5 == 4 {
        String::new()
    } else if i % 7 == 3 {
        format!("{tag} long note number {i}")
    } else {
        format!("{tag}{i}")
    }
}

fn notes(tag: &str, r: std::ops::Range<usize>) -> Vec<String> {
    r.map(|i| note(tag, i)).collect()
}

#[test]
fn character_notes_regular_record_and_window() {
    let mut f = open(NOTES);
    let r = record(&mut f, "/P32/NOTES/FLOW/01JAN2001/1Hour/CNOTES REG/");
    // ztsRetrieveReg7: the whole January block, 744 hourly slots.
    assert_eq!(r.ts.len(), 744);
    assert_eq!(r.ts.times[0], at(2001, 1, 1, 3600));
    let v = f32s(&r);
    let cn = r.meta.cnotes.as_ref().unwrap();
    let q = r.ts.quality.as_ref().unwrap();
    for i in 0..744 {
        if i < 24 {
            assert_eq!(v[i], fv(10.0, i));
            assert_eq!(cn[i], note("n1-", i), "note {i}");
            assert_eq!(q[i], if i % 3 == 0 { 3 } else { 5 });
        } else {
            assert_eq!(v[i].to_bits(), FLT_MAX_NEG.to_bits());
            assert_eq!(cn[i], "");
            assert_eq!(q[i], 0);
        }
    }
    assert_eq!(r.meta.quality_element_size, 1);
    assert_eq!(r.meta.inotes_element_size, 0);
    // Window 03:00-09:00: HEC returns 7 values with their notes.
    let w = dataset(
        &mut f,
        "/P32/NOTES/FLOW//1Hour/CNOTES REG/",
        Some((at(2001, 1, 1, 3 * 3600), at(2001, 1, 1, 9 * 3600))),
    );
    assert_eq!(w.meta.cnotes.as_deref().unwrap(), &notes("n1-", 2..9)[..]);
    assert_eq!(f32s(&w), &fvs(10.0, 2..9)[..]);
}

#[test]
fn integer_notes_regular_record() {
    let mut f = open(NOTES);
    let r = record(&mut f, "/P32/NOTES/FLOW/01JAN2001/1Hour/INOTES REG/");
    assert_eq!(r.meta.inotes_element_size, 2);
    let n = r.meta.inotes.as_ref().unwrap();
    assert_eq!(n.len(), 744 * 2);
    for (i, &w) in n.iter().enumerate() {
        assert_eq!(w, if i < 48 { 1000 + i as i32 } else { 0 });
    }
    assert!(r.meta.cnotes.is_none());
    assert!(r.ts.quality.is_none());
}

#[test]
fn notes_stitched_across_year_blocks() {
    let mut f = open(NOTES);
    // Doubles with character notes, 11DEC2001 .. 19JAN2002 daily.
    let d = dataset(&mut f, "/P32/NOTES/STAGE//1Day/CNOTES DBL/", None);
    assert_eq!(d.ts.len(), 40);
    assert_eq!(d.meta.blocks_found, 2);
    assert_eq!(d.ts.times[0], at(2001, 12, 11, 0));
    assert_eq!(d.ts.times[39], at(2002, 1, 19, 0));
    let want = notes("n3-", 0..40);
    assert_eq!(d.meta.cnotes.as_deref().unwrap(), &want[..]);
    assert_eq!(f64s(&d), &dvs(30.0, 0..40)[..]);
    // Window 28DEC2001 2400 .. 05JAN2002 2400: 9 values, notes 18..26.
    let w = dataset(
        &mut f,
        "/P32/NOTES/STAGE//1Day/CNOTES DBL/",
        Some((at(2001, 12, 29, 0), at(2002, 1, 6, 0))),
    );
    assert_eq!(w.ts.len(), 9);
    assert_eq!(w.meta.cnotes.as_deref().unwrap(), &want[18..27]);
    // Integer notes of 3 words plus quality, same two blocks.
    let d = dataset(&mut f, "/P32/NOTES/STAGE//1Day/INOTES QUAL/", None);
    assert_eq!(d.meta.inotes_element_size, 3);
    let want: Vec<i32> = (0..120).map(|i| -5000 + 7 * i).collect();
    assert_eq!(d.meta.inotes.as_deref().unwrap(), &want[..]);
    let q: Vec<i32> = (1..=40).collect();
    assert_eq!(d.ts.quality.as_deref().unwrap(), &q[..]);
    let w = dataset(
        &mut f,
        "/P32/NOTES/STAGE//1Day/INOTES QUAL/",
        Some((at(2001, 12, 31, 0), at(2002, 1, 3, 0))),
    );
    assert_eq!(w.ts.len(), 4);
    assert_eq!(w.meta.inotes.as_deref().unwrap(), &want[20 * 3..24 * 3]);
}

#[test]
fn irregular_notes() {
    let mut f = open(NOTES);
    // Character notes across two IR-Month blocks (4 in January, 8 in February).
    let d = dataset(&mut f, "/P32/NOTES/FLOW//IR-Month/CNOTES IRR/", None);
    assert_eq!(d.ts.len(), 12);
    assert_eq!(d.meta.blocks_found, 2);
    let t0 = at(2001, 1, 26, 0);
    for i in 0..12 {
        assert_eq!(d.ts.times[i], t0 + i as i64 * 37 * 3600);
    }
    let want = notes("i5-", 0..12);
    assert_eq!(d.meta.cnotes.as_deref().unwrap(), &want[..]);
    let r = record(&mut f, "/P32/NOTES/FLOW/01FEB2001/IR-Month/CNOTES IRR/");
    assert_eq!(r.meta.cnotes.as_deref().unwrap(), &want[4..]);
    let w = dataset(
        &mut f,
        "/P32/NOTES/FLOW//IR-Month/CNOTES IRR/",
        Some((at(2001, 1, 30, 0), at(2001, 2, 2, 0))),
    );
    assert_eq!(w.meta.cnotes.as_deref().unwrap(), &want[3..5]);
    // Integer notes of 4 words, doubles.
    let r = record(&mut f, "/P32/NOTES/FLOW/01MAR2001/IR-Month/INOTES IRR/");
    assert_eq!(r.meta.inotes_element_size, 4);
    let want: Vec<i32> = (0..40).map(|i| 77 * i - 3).collect();
    assert_eq!(r.meta.inotes.as_deref().unwrap(), &want[..]);
    assert_eq!(f64s(&r), &dvs(60.0, 0..10)[..]);
    assert_eq!(r.ts.times[9], at(2001, 3, 3, 9 * 300 * 60));
}

#[test]
fn quality_with_more_than_one_word() {
    let mut f = open(NOTES);
    // Two words per value, regular floats.
    let r = record(&mut f, "/P32/QUALITY/FLOW/01JAN2001/1Hour/Q2 REG/");
    assert_eq!(r.meta.quality_element_size, 2);
    let words = r.meta.quality_words.as_ref().unwrap();
    assert_eq!(words.len(), 744 * 2);
    for (i, &w) in words.iter().enumerate().take(48) {
        let k = (i / 2) as i32;
        assert_eq!(w, if i % 2 == 0 { k * 16 + 1 } else { -k - 1 });
    }
    assert!(words[48..].iter().all(|&w| w == 0));
    // `ts.quality` keeps the first word per value.
    let q = r.ts.quality.as_ref().unwrap();
    assert_eq!(q.len(), 744);
    assert_eq!(q[1], 17);
    // Three words per value, doubles across two year blocks.
    let d = dataset(&mut f, "/P32/QUALITY/STAGE//1Day/Q3 DBL/", None);
    assert_eq!(d.meta.quality_element_size, 3);
    let want: Vec<i32> = (0..120).map(|i| 0x100 * (i % 3) + i).collect();
    assert_eq!(d.meta.quality_words.as_deref().unwrap(), &want[..]);
    let w = dataset(
        &mut f,
        "/P32/QUALITY/STAGE//1Day/Q3 DBL/",
        Some((at(2001, 12, 26, 0), at(2002, 1, 11, 0))),
    );
    assert_eq!(w.ts.len(), 17);
    assert_eq!(
        w.meta.quality_words.as_deref().unwrap(),
        &want[15 * 3..32 * 3]
    );
    // Two words per value with character notes, irregular across two blocks.
    let d = dataset(&mut f, "/P32/QUALITY/FLOW//IR-Month/Q2 IRR/", None);
    let want: Vec<i32> = (0..24).map(|i| 3 + 11 * i).collect();
    assert_eq!(d.meta.quality_words.as_deref().unwrap(), &want[..]);
    assert_eq!(d.meta.cnotes.as_deref().unwrap(), &notes("q3-", 0..12)[..]);
}

#[test]
fn quality_words_follow_the_missing_value_trim() {
    let mut f = open(NOTES);
    // 24 values from 01JAN2001 1300; value 0 is -901, 5 is -902, 23 is -FLT_MAX.
    let opts = TsReadOptions {
        window: None,
        trim_missing: true,
    };
    let t = f
        .read_ts(b"/P32/QUALITY/FLOW//1Hour/Q2 MISSING/", &opts)
        .unwrap();
    // ztsRetrieve(retrieveFlag -1): 22 values, the -902 inside kept.
    assert_eq!(t.ts.len(), 22);
    assert_eq!(t.ts.times[0], at(2001, 1, 1, 14 * 3600));
    assert_eq!(f32s(&t)[4], -902.0);
    let want: Vec<i32> = (2..46).map(|i| 9 * i + 2).collect();
    assert_eq!(t.meta.quality_words.as_deref().unwrap(), &want[..]);
}

#[test]
fn pseudo_regular_e_parts() {
    let mut f = open(IRREG);
    // ~1Day is stored as irregular data in IR-Year blocks (01JAN2001, 01JAN2002).
    let d = dataset(&mut f, "/P32/PSEUDO/FLOW//~1Day/PR DAY/", None);
    assert!(d.meta.interval.pseudo_regular);
    assert_eq!(
        d.ts.kind,
        TsKind::Irregular {
            block: IrregularBlock::Year
        }
    );
    assert_eq!(d.meta.blocks_found, 2);
    let t0 = at(2001, 12, 27, 0);
    let want: Vec<i64> = (0..10)
        .map(|i| t0 + 86_400 * (i + if i >= 6 { 3 } else { 0 }))
        .collect();
    assert_eq!(d.ts.times, want);
    assert_eq!(f32s(&d), &fvs(1.0, 0..10)[..]);
    // 01JAN2002 00:00 (31DEC2001 24:00) belongs to the 2001 block.
    let r = record(&mut f, "/P32/PSEUDO/FLOW/01JAN2001/~1Day/PR DAY/");
    assert_eq!(r.ts.len(), 6);
    // ~6Hour (IR-Year blocks) and ~1Month (IR-Century blocks, D part 01JAN2000):
    // ztsGetStandardInterval.c (7-IU-15) lines 193-216, the DSS7 branch, puts 6 hours and
    // up to a week in years and 1Month (not below SECS_IN_1_MONTH) in centuries.
    let d = dataset(&mut f, "/P32/PSEUDO/FLOW//~6Hour/PR 6HOUR/", None);
    assert_eq!(
        d.ts.kind,
        TsKind::Irregular {
            block: IrregularBlock::Year
        }
    );
    assert_eq!(d.ts.times[0], at(2001, 6, 15, 6 * 3600));
    assert_eq!(d.ts.times[7], at(2001, 6, 17, 0));
    assert_eq!(f64s(&d), &dvs(2.0, 0..8)[..]);
    let r = record(&mut f, "/P32/PSEUDO/FLOW/01JAN2000/~1Month/PR MONTH/");
    assert_eq!(
        r.ts.kind,
        TsKind::Irregular {
            block: IrregularBlock::Century
        }
    );
    assert_eq!(r.ts.data_type, "PER-AVER");
    let t0 = at(2001, 1, 1, 0);
    let want: Vec<i64> = (0..6).map(|i| t0 + 86_400 * (31 * i + 14)).collect();
    assert_eq!(r.ts.times, want);
}

#[test]
fn ir_century_with_minute_times() {
    let mut f = open(IRREG);
    let years = [1950, 1960, 1970, 1980, 1990, 1999, 2005, 2020];
    let want: Vec<i64> = years
        .iter()
        .enumerate()
        .map(|(i, &y)| at(y, 3, 15, (390 + i as i64) * 60))
        .collect();
    let d = dataset(&mut f, "/P32/CENTURY/FLOW//IR-Century/MINUTES/", None);
    assert_eq!(d.ts.times, want);
    assert_eq!(d.meta.blocks_found, 2);
    assert_eq!(d.meta.time_granularity_seconds, 60);
    let r = record(&mut f, "/P32/CENTURY/FLOW/01JAN1900/IR-Century/MINUTES/");
    assert_eq!(r.ts.times, want[..6]);
    let w = dataset(
        &mut f,
        "/P32/CENTURY/FLOW//IR-Century/MINUTES/",
        Some((at(1985, 1, 1, 0), at(2011, 1, 1, 0))),
    );
    assert_eq!(w.ts.times, want[4..7]);
}

#[test]
fn second_granularity_far_past_and_future() {
    let mut f = open(IRREG);
    // IR-Year 2350-2351 (julian base 01JAN2350).
    let d = dataset(&mut f, "/P32/SECONDS/FLOW//IR-Year/FUTURE 2350/", None);
    let want: Vec<i64> = (0..6)
        .map(|i| at(2350, 1, 1, 86_400 * 100 * i + 3600 * i + 17 * i + 1))
        .collect();
    assert_eq!(d.ts.times, want);
    assert_eq!(d.meta.time_granularity_seconds, 1);
    assert_eq!(d.meta.blocks_found, 2);
    // A value one second into the block: HEC's C library returns it; Monolith 3.3.27's
    // record read starts its window at 00:01 and does not.
    let r = record(&mut f, "/P32/SECONDS/FLOW/01JAN2350/IR-Year/FUTURE 2350/");
    assert_eq!(r.ts.times[0], at(2350, 1, 1, 1));
    assert_eq!(r.ts.len(), 4);
    // IR-Year 1650-1651, doubles.
    let d = dataset(&mut f, "/P32/SECONDS/FLOW//IR-Year/PAST 1650/", None);
    let want: Vec<i64> = (0..6)
        .map(|i| at(1650, 1, 1, 86_400 * (90 * i + 1) + 59 * i + 7))
        .collect();
    assert_eq!(d.ts.times, want);
    assert_eq!(d.ts.times[0], -7_889_011_193);
    assert_eq!(f64s(&d), &dvs(6.0, 0..6)[..]);
    // IR-Day on 04JUL7500.
    let d = dataset(&mut f, "/P32/SECONDS/FLOW//IR-Day/FUTURE 7500/", None);
    let want: Vec<i64> = (0..5).map(|i| at(7500, 7, 4, 1 + 13 * i * i)).collect();
    assert_eq!(d.ts.times, want);
    assert_eq!(d.ts.times[0], 176_734_915_201);
    let w = dataset(
        &mut f,
        "/P32/SECONDS/FLOW//IR-Day/FUTURE 7500/",
        Some((at(7500, 7, 4, 60), at(7500, 7, 4, 3600))),
    );
    assert_eq!(w.ts.times, want[3..]);
    // IR-Decade from 1808 into the 1810s.
    let d = dataset(&mut f, "/P32/SECONDS/FLOW//IR-Decade/PAST 1808/", None);
    let want: Vec<i64> = (0..4)
        .map(|i| at(1808, 1, 1, 86_400 * 400 * i + 3601))
        .collect();
    assert_eq!(d.ts.times, want);
    assert_eq!(d.meta.block_pathnames.len(), 2);
}

#[test]
fn irregular_pattern_times_count_granularity_units() {
    let mut f = open(IRREG);
    // Type 111, minute granularity: stored times 120, 86520, ... minutes from julian 0.
    // ztsRetrievePattern.c (7-IU-15) lines 330 and 365; HEC's C library and Monolith
    // 3.3.27 both give 7200 s for the first value. Before P32 the engine returned 120.
    let r = record(&mut f, "/P32/PATTERN/FLOW/TS-PATTERN/IR-Year/IRR PATTERN/");
    assert_eq!(r.ts.record_type, 111);
    assert!(r.meta.pattern);
    let want: Vec<i64> = (0..5).map(|i| (1440 * 60 * i + 120) * 60).collect();
    assert_eq!(r.ts.times, want);
    assert_eq!(f32s(&r), &fvs(9.0, 0..5)[..]);
    // Type 116, doubles.
    let r = record(
        &mut f,
        "/P32/PATTERN/FLOW/TS-PATTERN/IR-Day/IRR PATTERN DBL/",
    );
    assert_eq!(r.ts.record_type, 116);
    assert_eq!(r.ts.times, vec![1800, 7200, 12_600, 18_000]);
    assert_eq!(f64s(&r), &dvs(10.0, 0..4)[..]);
    // A regular pattern (101) in the same file keeps its pattern time convention.
    let r = record(&mut f, "/P32/PATTERN/FLOW/TS-PATTERN/1Month/REG PATTERN/");
    assert_eq!(r.ts.record_type, 101);
    assert_eq!(r.ts.len(), 12);
}

#[test]
fn aliases_read_their_primary() {
    let mut f = open(CATALOG);
    let primary = record(&mut f, "/P32/ALIAS PRIMARY/FLOW/01JAN2001/1Day/OBS/");
    for alias in [
        "/P32/ALIAS ONE/FLOW/01JAN2001/1Day/OBS/",
        "/P32/ALIAS TWO/STAGE/01JAN2001/1Day/ALT/",
    ] {
        let rec = f.lookup(alias.as_bytes()).unwrap().unwrap();
        assert_eq!(rec.status, 2);
        // P32 fix: the primary info block is read with the primary's pathname length,
        // so its pathname is the primary's (zaliasGetPrimary.c lines 126-138).
        assert_eq!(
            rec.info.pathname,
            b"/P32/ALIAS PRIMARY/FLOW/01Jan2001/1Day/OBS/".to_vec()
        );
        let r = f.read_ts_record(&rec).unwrap();
        assert_eq!(r.ts.values, primary.ts.values);
        assert_eq!(r.ts.times, primary.ts.times);
    }
    // Dataset reads through the alias: both years are aliased for ALIAS ONE, only 2001
    // for ALIAS TWO (22 values: 11DEC2001 .. 01JAN2002 00:00 = 31DEC2001 24:00).
    let d = dataset(&mut f, "/P32/ALIAS ONE/FLOW//1Day/OBS/", None);
    assert_eq!(d.ts.len(), 40);
    assert_eq!(f32s(&d), &fvs(1.0, 0..40)[..]);
    let d = dataset(&mut f, "/P32/ALIAS TWO/STAGE//1Day/ALT/", None);
    assert_eq!(d.ts.len(), 22);
    // A removed alias is not found.
    assert!(f
        .lookup(b"/P32/ALIAS GONE/FLOW/01JAN2001/1Day/OBS/")
        .unwrap()
        .is_none());
}

#[test]
fn catalog_statuses_after_alias_delete_and_rename() {
    let mut f = open(CATALOG);
    let cat = f.catalog().unwrap();
    let mut seen = std::collections::BTreeMap::new();
    for (e, m) in cat.catalog.entries.iter().zip(&cat.meta) {
        let p = String::from_utf8(e.pathname.clone()).unwrap();
        seen.insert(p, (m.raw_status, e.status));
    }
    assert_eq!(seen.len(), 16);
    let st = |p: &str| seen.get(p).copied().expect(p);
    let alias1 = "/P32/ALIAS ONE/FLOW/01JAN2001/1Day/OBS/";
    assert_eq!(st(alias1), (2, RecordStatus::Alias));
    let deleted = "/P32/EDIT/FLOW/01Jan2001/1Hour/DELETED/";
    assert_eq!(st(deleted), (11, RecordStatus::Deleted));
    let old = "/P32/EDIT/FLOW/01Jan2001/1Hour/OLD NAME/";
    assert_eq!(st(old), (12, RecordStatus::Renamed));
    let new = "/P32/EDIT/FLOW/01JAN2001/1Hour/NEW NAME/";
    assert_eq!(st(new), (1, RecordStatus::Live));
    // zundelete leaves status 0; a store leaves 1.
    let undeleted = "/P32/EDIT/FLOW/01Jan2001/1Hour/UNDELETED/";
    assert_eq!(st(undeleted), (0, RecordStatus::Live));
    // zaliasRemove.c (7-IU-15) lines 150-162 sets status 13 and stores one character
    // fewer "so will not match in zcheck": the bin pathname loses its final slash.
    let gone = "/P32/ALIAS GONE/FLOW/01JAN2001/1Day/OBS";
    assert_eq!(st(gone), (13, RecordStatus::Deleted));
    // HEC's statusWanted 0 catalog: live and alias entries, 13 pathnames.
    let live = cat
        .catalog
        .entries
        .iter()
        .filter(|e| matches!(e.status, RecordStatus::Live | RecordStatus::Alias))
        .count();
    assert_eq!(live, 13);
    for gone in [
        "/P32/EDIT/FLOW/01JAN2001/1Hour/DELETED/",
        "/P32/EDIT/FLOW/01JAN2001/1Hour/OLD NAME/",
    ] {
        assert!(f.lookup(gone.as_bytes()).unwrap().is_none(), "{gone}");
    }
}

#[test]
fn deleted_then_rewritten_and_renamed_records() {
    let mut f = open(CATALOG);
    // Written (12 values from 01:00), deleted, written again (6 values from 03:00): HEC
    // reads the second write only.
    let d = dataset(&mut f, "/P32/EDIT/FLOW//1Hour/READDED/", None);
    let v = f32s(&d);
    assert_eq!(v.len(), 24);
    assert_eq!(v[0].to_bits(), FLT_MAX_NEG.to_bits());
    assert_eq!(v[1].to_bits(), FLT_MAX_NEG.to_bits());
    assert_eq!(&v[2..8], &fvs(600.0, 0..6)[..]);
    let r = record(&mut f, "/P32/EDIT/FLOW/01JAN2001/IR-Month/IRR READDED/");
    assert_eq!(f32s(&r), &[1100.0, 1100.25, 1100.5]);
    assert_eq!(r.ts.times[0], at(2001, 1, 1, 7200));
    let r = record(&mut f, "/P32/EDIT/FLOW/01JAN2001/1Hour/NEW NAME/");
    assert_eq!(&f32s(&r)[..12], &fvs(900.0, 0..12)[..]);
    let r = record(&mut f, "/P32/EDIT/FLOW/01JAN2001/1Hour/UNDELETED/");
    assert_eq!(f32s(&r)[11], fv(800.0, 11));
}

#[test]
fn collection_members() {
    let mut f = open(CATALOG);
    let members = [
        ("000001", 100.0),
        ("000002", 200.0),
        ("000003", 300.0),
        ("ABCDEF", 400.0),
    ];
    for (seq, base) in members {
        let p = format!("/P32/COLLECTION/FLOW/01JAN2001/1Hour/C:{seq}|RUN SET/");
        let r = record(&mut f, &p);
        assert_eq!(&f32s(&r)[..12], &fvs(base, 0..12)[..]);
    }
    let w = dataset(
        &mut f,
        "/P32/COLLECTION/FLOW//1Hour/C:000003|RUN SET/",
        Some((at(2001, 1, 1, 3 * 3600), at(2001, 1, 1, 6 * 3600))),
    );
    assert_eq!(f32s(&w), &[300.5, 300.75, 301.0, 301.25]);
}
